import glob
import os
import re
import xml.etree.ElementTree as ET

root = "pptx_unpacked"
errors = []

# 1. All XML files must be well-formed
xml_files = []
for dirpath, _dirnames, filenames in os.walk(root):
    for fn in filenames:
        if fn.endswith((".xml", ".rels")):
            xml_files.append(os.path.join(dirpath, fn))
for path in sorted(xml_files):
    try:
        ET.parse(path)
    except ET.ParseError as e:
        errors.append(f"XML parse error in {path}: {e}")

# 2. Content_Types declares slide6
ct = open(os.path.join(root, "[Content_Types].xml"), encoding="ascii").read()
if '/ppt/slides/slide6.xml"' not in ct:
    errors.append("slide6.xml Override missing from [Content_Types].xml")

# 3. presentation.xml.rels maps rId13 -> slides/slide6.xml
rels = open(os.path.join(root, "ppt/_rels/presentation.xml.rels"), encoding="ascii").read()
if 'Id="rId13"' not in rels or "slides/slide6.xml" not in rels:
    errors.append("rId13 -> slide6.xml relationship missing")

# 4. presentation.xml slide list includes rId13 and count is 6
pres = open(os.path.join(root, "ppt/presentation.xml"), encoding="ascii").read()
sld_ids = re.findall(r'<p:sldId id="(\d+)" r:id="(rId\d+)"/>', pres)
if len(sld_ids) != 6:
    errors.append(f"Expected 6 slide entries, found {len(sld_ids)}")
if ("261", "rId13") not in sld_ids:
    errors.append("slide id 261 / rId13 not last in sldIdLst")

# 5. slide6.xml is well-formed, uses ctrTitle placeholder with the requested text
slide6 = open(os.path.join(root, "ppt/slides/slide6.xml"), encoding="ascii").read()
if 'type="ctrTitle"' not in slide6:
    errors.append("slide6.xml missing ctrTitle placeholder")
if "Thank you for your attention" not in slide6:
    errors.append("slide6.xml missing thank-you text")

# 6. slide6 rels references slideLayout1
s6rels = open(os.path.join(root, "ppt/slides/_rels/slide6.xml.rels"), encoding="ascii").read()
if "slideLayout1.xml" not in s6rels:
    errors.append("slide6 rels missing slideLayout1 reference")

# 7. No duplicate shape ids across slides (spot check on slide6)
ids = re.findall(r'<p:cNvPr id="(\d+)"', slide6)
if len(ids) != len(set(ids)):
    errors.append("duplicate shape ids in slide6.xml")

if errors:
    print("ERRORS:")
    for e in errors:
        print(" -", e)
    raise SystemExit(1)
print("OK: all XML well-formed; slide6 registered (Content_Types, rels, sldIdLst); text present:", "Thank you for your attention")

